	// We traverse i outermost and then restrict j to [0, i], which avoids
	// touching the upper triangular (never used by the kernel).
	traverser(L).template for_dims<'i'>([=](auto inner) {
		// state with current i fixed
		auto state_i = inner.state();
		auto i = get_index<'i'>(state_i);

		// restrict this row to the lower-triangular part: j in [0, i]
		inner.order(noarr::slice<'j'>(0, i + 1)).for_each([=](auto state_ij) {
			auto j = get_index<'j'>(state_ij);

			// identical formula as in the original code (integer arithmetic)
			L[state_ij] = (num_t)(i + n - j + 1) * 2 / n;
		});
	});
}

