// for i = 0..n-1:
//   x[i] = b[i];
//   for j = 0..i-1:
//     x[i] -= L[i][j] * x[j];
//   x[i] = x[i] / L[i][i];
[[gnu::flatten, gnu::noinline]]
void kernel_trisolv(auto L, auto x, auto b) {
	using namespace noarr;

#pragma scop
	// Traverse rows in increasing i; data dependency x[i] depends on x[0..i-1]
	traverser(L, x, b).template for_dims<'i'>([=](auto inner) {
		// state with current i fixed (no 'j' yet)
		auto state_i = inner.state();
		auto i = get_index<'i'>(state_i);

		// Work with x[i] in a register to reduce memory traffic
		num_t xi = b[state_i];

		if constexpr (USE_TRIANGULAR_SLICING) {
			// Optimized path:
			// only iterate j in [0, i); eliminates useless iterations and branches
			inner.order(noarr::slice<'j'>(0, i)).for_each([&](auto state_ij) {
				auto j = get_index<'j'>(state_ij);
				// state_ij has dimensions (i, j) at the correct indices
				xi -= L[state_ij] * x[noarr::idx<'i'>(j)];
