		auto i = get_index<'i'>(state);

		x[state] = static_cast<num_t>(-999);
		b[state] = static_cast<num_t>(i);
	});

	// initialize L as a lower triangular matrix:
	//  for i in [0, n)
	//    for j in [0, i]   (only lower triangle including diagonal)
	//
	// This avoids iterating the upper triangle at all (the original
	// version traversed the full n×n grid and skipped values with
	// an `if (j <= i)` condition).
	traverser(L)
		// Ensure 'i' is the outermost loop regardless of the chosen layout
		.order(noarr::hoist<'i'>())
		.template for_dims<'i'>([&](auto trav_i) {
			// State with current row index 'i' fixed
			auto state_i = trav_i.state();
			auto i = get_index<'i'>(state_i);

			// For this row, restrict 'j' to [0, i] (length i + 1)
			// This removes the need for a conditional on j inside the loop.
			auto row_trav = trav_i.order(noarr::slice<'j'>(0, i + 1));

			row_trav.for_each([&](auto state) {
				auto [ii, j] = get_indices<'i', 'j'>(state);
				// ii == i; using ii makes it explicit that we work with
				// the indices coming from the traversal state.
				L[state] = static_cast<num_t>(ii + n - j + 1) *
