	using namespace noarr;

#pragma scop
	// Outer loop over the 'i' dimension.
	// We start from a combined traverser(L, x, b) so all three arrays see
	// the same index state and then enforce 'i' as the outer dimension.
	traverser(L, x, b)
		.order(noarr::hoist<'i'>())
		.template for_dims<'i'>([&](auto trav_i) {
