// include benchmark-specific definitions (for trisolv)
#include "trisolv.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// Small tunable parameter: tile size along the inner j dimension
// Increasing this can help the compiler generate better vectorized code on
// some architectures by exposing a regular access pattern to L[i][j] and x[j].
// Must be >= 1. For TRI_J_BLOCK == 1 the kernel degenerates to a simple
// non-tiled version (still without extra j >= i iterations).
constexpr std::size_t TRI_J_BLOCK = 64;

// layouts for individual arrays
struct tuning {
	// L: i x j  (row i, column j, row-major: i outer, j inner)
	DEFINE_PROTO_STRUCT(l_layout, j_vec ^ i_vec);
	// x: i
	DEFINE_PROTO_STRUCT(x_layout, i_vec);
	// b: i
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// Array initialization.
// L: n x n lower triangular
// x: length n
// b: length n
void init_array(auto L, auto x, auto b) {
	using namespace noarr;

	// problem size from structure
	auto n = L | get_length<'i'>();

	// initialize x and b: for i in [0, n)
	// Use for_dims<'i'> so that 'i' is the explicit loop dimension,
	// which makes the traversal semantics obvious and avoids
	// computing/decoding the full index_state in the inner lambda.
	traverser(x, b).template for_dims<'i'>([=](auto inner) {
		auto state_i = inner.state();              // state with current i fixed
		auto i = get_index<'i'>(state_i);

		x[state_i] = (num_t)-999;
		b[state_i] = (num_t)i;
	});

	// initialize L: for i in [0, n), for j in [0, i] (strictly lower + diagonal)
	// We traverse only the lower-triangular part by slicing the j dimension
	// to [0, i+1) for each row i, instead of looping over all j and
	// guarding with an if (j <= i).
	traverser(L).template for_dims<'i'>([=](auto inner) {
		auto state_i = inner.state();              // state with current i fixed
		auto i = get_index<'i'>(state_i);

		// For this row, restrict j to the prefix [0, i+1).
		// This keeps the access pattern contiguous in memory
		// while avoiding useless iterations and branches.
		auto row_prefix = inner.order(noarr::slice<'j'>(0, i + 1));

		row_prefix.for_each([=](auto state) {
			auto j = get_index<'j'>(state);

			L[state] = (num_t)(i + n - j + 1) * 2 / n;
		});
	});
}

// Main computational kernel:
// for i = 0..n-1:
//   x[i] = b[i];
//   for j = 0..i-1:
//     x[i] -= L[i][j] * x[j];
//   x[i] = x[i] / L[i][i];
//
// Optimizations over the baseline version:
//
// 1) We avoid iterating j over [0, n) with a runtime "if (j < i)" guard
//    by slicing the j-dimension to exactly the active range [0, i).
//
// 2) We accumulate the current x[i] value in a scalar register (`xi`)
//    during the j-loop and write it back to memory only once per i.
//    This reduces memory traffic on x.
//
// 3) We optionally tile the inner j-loop into blocks of size TRI_J_BLOCK
//    using `noarr::into_blocks` and `noarr::hoist`. The tiling preserves
//    the original evaluation order (j increasing) while improving
//    data locality and making the inner loop size more regular for the
//    compiler's vectorizer.
//
//    For each i we split [0, i) into:
//      - a "full" prefix [0, full_len) where full_len is the largest
//        multiple of TRI_J_BLOCK not exceeding i; this part is traversed
//        in tiles.
//      - a (possibly empty) tail [full_len, i) processed without tiling.
//    This guarantees that `into_blocks` always sees a j-length that is
//    a multiple of the tile size, as required.
[[gnu::flatten, gnu::noinline]]
void kernel_trisolv(auto L, auto x, auto b) {
	using namespace noarr;

#pragma scop
	// Outer loop over i – this must remain sequential because x[i]
	// depends on all x[j] with j < i (forward substitution on L).
	traverser(L).template for_dims<'i'>([&](auto inner) {
		// State with current i fixed; contains only index_in<'i'>
		auto state_i = inner.state();
		auto i = get_index<'i'>(state_i);

		// Start from the right-hand side value b[i]; keep it in a register.
		num_t xi = b[state_i];

		// Limit of the inner j-loop: j in [0, i)
		const std::size_t j_limit = i;

		// Length of the fully-tiled prefix of [0, j_limit)
		const std::size_t full_len =
			(j_limit / TRI_J_BLOCK) * TRI_J_BLOCK; // largest multiple of TRI_J_BLOCK <= j_limit

		// ------------------------------------------------------------------
		// 1) Tiled part: j in [0, full_len), processed in blocks of size
		//    TRI_J_BLOCK. We first slice j to [0, full_len), then split
		//    that range into ("J", "j") using into_blocks, and hoist "J"
		//    to the outermost loop. The final traversal order is:
		//      for J = 0 .. full_len/TRI_J_BLOCK - 1
		//        for j = 0 .. TRI_J_BLOCK - 1
		//          global_j = J*TRI_J_BLOCK + j
		//    which is exactly the original j in increasing order.
		// ------------------------------------------------------------------
		if (full_len > 0) {
			auto tiled_proto =
				noarr::slice<'j'>(0, full_len) ^
				noarr::into_blocks<'j', 'J', 'j'>(TRI_J_BLOCK) ^
				noarr::hoist<'J'>();

			inner.order(tiled_proto).for_each([&](auto state) {
				auto j = get_index<'j'>(state); // 0 <= j < full_len

				// Forward substitution update:
				//   xi -= L[i][j] * x[j]
				// The state already contains the fixed 'i' index and the
				// current 'j' index, so it can be used directly with L.
				xi -= L[state] * x[noarr::idx<'i'>(j)];
			});
		}

		// ------------------------------------------------------------------
		// 2) Tail part: j in [full_len, j_limit) – at most TRI_J_BLOCK-1
		//    elements. We handle this without tiling to keep the control
		//    logic simple while still avoiding any j >= i iterations.
		// ------------------------------------------------------------------
		if (full_len < j_limit) {
			auto tail_len = j_limit - full_len;

			auto tail_proto = noarr::slice<'j'>(full_len, tail_len);

			inner.order(tail_proto).for_each([&](auto state) {
				auto j = get_index<'j'>(state); // full_len <= j < j_limit

				xi -= L[state] * x[noarr::idx<'i'>(j)];
			});
		}

		// Divide by the diagonal element L[i][i]
		auto diag_state = noarr::idx<'i', 'j'>(i, i);
		xi /= L[diag_state];

		// Write the final value back once
		x[state_i] = xi;
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// set lengths for dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data (bags own the memory)
	auto L = noarr::bag(noarr::scalar<num_t>() ^ tuning.l_layout ^ set_lengths);
	auto x = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto b = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(L.get_ref(), x.get_ref(), b.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_trisolv(L.get_ref(), x.get_ref(), b.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (prevents dead-code elimination of computation)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x.get_ref());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
