#include "trisolv.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// layouts for individual arrays
struct tuning {
	// L: i x j  (row i, column j)
	// Use row-major layout: 'i' is the outer dimension, 'j' the inner one
	// to make accesses L[i][j] for increasing j contiguous in memory.
	DEFINE_PROTO_STRUCT(l_layout, j_vec ^ i_vec);
	// x: i
	DEFINE_PROTO_STRUCT(x_layout, i_vec);
	// b: i
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// Array initialization.
// L: n x n lower triangular
// x: length n
// b: length n
void init_array(auto L, auto x, auto b) {
	using namespace noarr;

	// problem size from structure
	auto n = L | get_length<'i'>();

	// initialize x and b: for i in [0, n)
	traverser(x, b).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x[state] = (num_t)-999;
		b[state] = (num_t)i;
	});

	// initialize L:
	// for i in [0, n)
	//   for j in [0, i]  (lower triangular including diagonal)
	//
	// Instead of traversing the full i×j rectangle and guarding with
	//   if (j <= i)
	// we restrict the inner traversal to j ∈ [0, i+1) using slice<'j'>.
	// This removes the conditional from the inner loop and improves
	// branch prediction and vectorization opportunities.
	traverser(L).template for_dims<'i'>([=](auto trav_i) {
		// state with current i fixed
		auto state_i = trav_i.state();
		auto i = get_index<'i'>(state_i);

		// Restrict traversal in 'j' to [0, i+1) so that only the lower
		// triangle (including the diagonal) is initialized.
		auto trav_ij = trav_i.order(noarr::slice<'j'>(0, i + 1));

		trav_ij.for_each([=](auto state_ij) {
			auto j = get_index<'j'>(state_ij);

			L[state_ij] = (num_t)(i + n - j + 1) * (num_t)2 / (num_t)n;
		});
	});
}

// Main computational kernel (forward substitution for a lower-triangular
// system L x = b):
//
// for i = 0..n-1:
//   x[i] = b[i];
//   for j = 0..i-1:
//     x[i] -= L[i][j] * x[j];
//   x[i] = x[i] / L[i][i];
//
// Optimizations:
// - Traverse in 'i' outermost (as in the original algorithm) to respect the
//   data dependency x[i] depending on x[0..i-1].
// - Use a scalar accumulator for x[i] to minimize loads/stores to x[i].
// - Use noarr::slice<'j'>(0, i) to avoid a data-dependent "if (j < i)"
//   inside the inner loop; this yields a clean, branch-free dot product
//   over contiguous data L[i][0..i-1] and x[0..i-1].
[[gnu::flatten, gnu::noinline]]
void kernel_trisolv(auto L, auto x, auto b) {
	using namespace noarr;

#pragma scop
	// Traverse with 'i' as the outermost dimension, matching the original
	// forward-substitution ordering.
	traverser(L, x, b).template for_dims<'i'>([=](auto inner_i) {
		// State with current i fixed (j is not yet set here)
		auto state_i = inner_i.state();
		auto i = get_index<'i'>(state_i);

		// Accumulator for x[i], kept in a register for the whole j-loop.
		// Start from b[i] as in the original algorithm.
		num_t xi = b[state_i];

		// Inner traversal over j in [0, i):
		// using slice<'j'>(0, i) avoids a conditional "if (j < i)" and
		// still traverses a contiguous prefix of the j-dimension.
		auto j_trav = inner_i.order(noarr::slice<'j'>(0, i));

		j_trav.for_each([&](auto state_ij) {
			auto j = get_index<'j'>(state_ij);

			// L[i][j] is addressed by state_ij (i and j are both set there).
			// x[j] is addressed by a separate state that fixes 'i' = j.
			xi -= L[state_ij] * x[noarr::idx<'i'>(j)];
		});

		// Divide by the diagonal element L[i][i].
		auto diag_state = noarr::idx<'i', 'j'>(i, i);
		xi /= L[diag_state];

		// Store the final result back to x[i].
		x[state_i] = xi;
	});
#pragma endscop
}

} // namespace

